import './DataTable.css';

export type Row = Record<string, string | number>;

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_COUNT = 5;

function PlaceholderRows({ columnCount }: { columnCount: number }): JSX.Element {
  return (
    <>
      {Array.from({ length: PLACEHOLDER_COUNT }, (_, rowIndex) => (
        <tr key={rowIndex} className="data-table-row">
          {Array.from({ length: columnCount }, (__, colIndex) => (
            <td key={colIndex} className="data-table-shimmer-cell">
              <div className="data-table-shimmer-bar" />
            </td>
          ))}
        </tr>
      ))}
    </>
  );
}

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
  const columnCount = columns.length > 0 ? columns.length : 3;

  return (
    <table role="table" className="data-table">
      {columns.length > 0 && (
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col} scope="col" className="data-table-header-cell">
                {col}
              </th>
            ))}
          </tr>
        </thead>
      )}
      <tbody>
        {loading ? (
          <PlaceholderRows columnCount={columnCount} />
        ) : (
          rows.map((row, rowIndex) => (
            <tr key={rowIndex} className="data-table-row">
              {Object.values(row).map((cell, colIndex) => (
                <td key={colIndex} className="data-table-cell">
                  {cell}
                </td>
              ))}
            </tr>
          ))
        )}
      </tbody>
    </table>
  );
}
